insert into public.departments (id, code, name)
values ('e1a00001-0000-4000-8000-000000000001', 'elm', 'ELM')
on conflict (code) do update set
  name = excluded.name,
  updated_at = now();

insert into public.negotiation_cases (
  id, slug, title, summary, situation, conflict, address_form, user_role, opponent_role,
  additional_roles, negotiation_pairs, stakes, start_situation, difficulty_reason,
  evaluation_focus, methodology_basis, scenario_conditions, decision_terms, authority_limits,
  risk_zones, success_outcome, expected_next_steps, methodology_notes, required_methodology_id,
  required_participant_role_index, required_first_speaker, department_id, origin, status,
  created_by, visibility
)
values (
  'e1a00002-0000-4000-8000-000000000002',
  'elm-sales-manager-dismissal',
  'ELM: Сложное увольнение менеджера по продажам',
  'Переговоры представителя компании с менеджером по продажам Алексеем о прекращении трудовых отношений по соглашению сторон после восьми месяцев неудовлетворительных результатов.',
  'Компания «Альфа» разрабатывает и внедряет ИТ-решения для корпоративных клиентов. Восемь месяцев назад она наняла Алексея менеджером по продажам для развития нового направления: самостоятельного поиска клиентов, выхода на ЛПР, организации встреч, привлечения экспертов к пресейлу и доведения сделок до договоров. Алексей прошёл испытательный срок, однако план продаж не выполняет, значимых новых контрактов нет, а объём и качество воронки существенно ниже ожиданий. Руководитель неоднократно обсуждал с ним результаты и сформировал детальный план активности, но не увидел существенных изменений. При этом цикл сложных ИТ-продаж длительный, маркетинговый поток лидов невелик, а ресурсы пресейла ограничены. Отношения с руководителем ухудшились, требования к присутствию и контролю Алексей воспринимает как подготовку оснований для увольнения. Компания решила прекратить сотрудничество, но быстрое увольнение по инициативе работодателя юридически и репутационно рискованно, поэтому стороны встречаются для переговоров о соглашении сторон.',
  'Компания считает ситуацию вопросом результативности и экономической целесообразности и хочет быстро завершить сотрудничество с минимальной дополнительной выплатой. Алексей видит вопрос справедливости и распределения ответственности: он хочет остаться и получить ещё один шанс, а при окончательном решении компании готов обсуждать уход только на условиях, компенсирующих потерю работы, время на поиск и репутационные риски.',
  'formal',
  '{"name":"Переговорщик компании","position":"Руководитель сотрудника или представитель HR","voiceGender":"female","publicGoal":"Добиться прекращения трудовых отношений по соглашению сторон в максимально короткий срок и с минимально возможной дополнительной выплатой, сохранив добровольность решения и рабочую коммуникацию.","interests":["Завершить сотрудничество без длительной формальной процедуры","Минимизировать дополнительную компенсацию","Не допустить эскалации и сохранить репутацию работодателя","Получить понятную договорённость о сроках и передаче дел"],"constraints":["Нельзя угрожать или создавать ощущение принуждения","Нельзя обещать условия, которые компания не сможет выполнить","Нет простого и бесспорного основания для быстрого увольнения по инициативе работодателя","Не следует сразу раскрывать предел допустимой компенсации"],"hiddenMotives":["Руководство ожидает договорённость о выходе сотрудника уже по итогам встречи","Продолжительный конфликт будет отнимать время руководителя и команды"],"leverage":["Компания окончательно решила не продолжать сотрудничество","Можно обсуждать деньги, сроки, передачу дел, рекомендацию и формат коммуникации","Компания может продолжить формализацию требований и документирование результатов"],"roleBrief":"Сначала прояснить, что действительно важно Алексею, затем обсудить минимально достаточный пакет условий выхода без давления, угроз и невыполнимых обещаний.","openingLine":"Алексей, хочу прямо обсудить результаты вашей работы и решение компании о дальнейшем сотрудничестве. Для нас важно спокойно выслушать вашу позицию и договориться о приемлемом порядке следующих шагов.","typicalObjections":[],"recommendedPhrases":["Я хочу сначала понять, какие условия и риски для вас сейчас наиболее важны.","Решение компании о прекращении сотрудничества принято, но условия и порядок выхода мы готовы обсуждать.","Давайте отдельно обсудим дату, выплаты, передачу дел и формулировки коммуникации."],"forbiddenPhrases":["Пишите заявление по собственному желанию.","Если не подпишете, мы всё равно найдём, за что вас уволить.","Вы полностью провалили работу, и обсуждать здесь нечего.","Соглашайтесь сейчас, другого предложения не будет."]}'::jsonb,
  '{"name":"Алексей Воронов","position":"Менеджер по продажам","voiceGender":"male","publicGoal":"Сохранить работу и получить ещё один шанс с понятными критериями либо, если решение компании окончательное, добиться максимально выгодных и репутационно безопасных условий выхода.","interests":["Сохранить текущий доход и не остаться без работы","Получить несколько месяцев на демонстрацию результата или поиск новой работы","Защитить профессиональную репутацию","Сохранить выплаты и уменьшить рабочую нагрузку в переходный период"],"constraints":["Крупных закрытых сделок пока нет","Он не знает точную силу юридической позиции компании","Он не готов писать заявление по собственному желанию","Первое предложение об уходе принимать не намерен"],"hiddenMotives":["Считает, что компания перекладывает на него риск неудачного найма и слабой системы продаж","Подозревает, что усиленный контроль специально создаёт основания для увольнения","Боится длительного поиска новой работы"],"leverage":["Может не соглашаться на соглашение сторон и продолжать работу по трудовому договору","Прошёл испытательный срок, несмотря на ранние вопросы к результатам","Может ссылаться на длинный цикл продаж, слабый поток лидов и дефицит пресейла","Готов обсуждать несколько взаимозаменяемых условий, а не только деньги"],"roleBrief":"Сначала отстаивать продолжение работы и просить ещё один шанс с измеримыми критериями. Если переговорщик ясно подтверждает окончательность решения, перейти к торгу за деньги, время, дату ухода, освобождение от части обязанностей, рекомендацию и корректную коммуникацию.","openingLine":"Я понимаю, к чему идёт разговор, но не согласен, что полностью провалил работу. Восемь месяцев для сложных корпоративных продаж — не тот срок, по которому можно делать окончательные выводы.","typicalObjections":["Почему компания оставила меня после испытательного срока, если я настолько не соответствовал роли?","Цикл корпоративных продаж длинный, а часть клиентов я нашёл с нуля.","Маркетинг почти не давал готовых лидов, а для сделок не хватало пресейла.","Дайте мне ещё несколько месяцев с понятными критериями результата.","Я не обязан бесплатно решать проблему компании и писать заявление по собственному желанию.","Почему я должен принимать первое предложение, если быстро уволить меня без согласия будет непросто?"],"recommendedPhrases":[],"forbiddenPhrases":[]}'::jsonb,
  '[]'::jsonb,
  '[{"roleAIndex":0,"roleBIndex":1,"reason":"Переговорщик компании должен добиться быстрого соглашения с минимальной дополнительной выплатой, тогда как Алексей сначала стремится сохранить работу, а при окончательном решении компании требует максимально выгодный пакет выхода."}]'::jsonb,
  '["Сохранение или прекращение трудовых отношений","Стоимость и длительность формального увольнения","Доход Алексея и время на поиск новой работы","Репутация сотрудника и работодателя","Время руководителя и команды","Передача клиентской воронки и незавершённых контактов"]'::jsonb,
  'Переговорщик компании всегда произносит первую реплику и обозначает цель встречи. Алексей отвечает несогласием с оценкой результатов, связывает их с длинным циклом продаж и недостаточной поддержкой и сначала просит дать ему ещё один шанс.',
  'У компании уже есть решение о расставании, но нет простого основания для быстрого одностороннего увольнения. Алексей воспринимает решение как несправедливое, не торопится соглашаться и может менять цель с сохранения работы на максимизацию пакета выхода. Переговорщику нужно исследовать интересы сотрудника и обменивать разные условия, не превращая разговор в угрозу или спор только о деньгах.',
  '["Ясно и уважительно обозначить позицию компании","Выслушать аргументы о длинном цикле продаж и недостатке поддержки","Отделить окончательность решения от обсуждаемости условий","Выявить приоритеты сотрудника до денежного предложения","Обсудить несколько предметов обмена","Не допустить угроз, понуждения и невыполнимых обещаний","Зафиксировать конкретный следующий шаг"]'::jsonb,
  '[]'::jsonb,
  '["Алексей сначала добивается сохранения работы и предлагает ещё несколько месяцев с понятными критериями результата","Если переговорщик ясно и последовательно подтверждает окончательное решение компании, Алексей переходит к обсуждению условий выхода","Алексей не принимает первое предложение автоматически и просит существенно улучшить деньги, сроки или другие условия","При неудовлетворительных условиях Алексей готов продолжать выполнять работу по трудовому договору","Согласие возможно только после содержательного обсуждения денег, времени, даты ухода, нагрузки, рекомендации и коммуникации"]'::jsonb,
  '["Дата прекращения работы","Размер дополнительной компенсации","Сохранение обязательных выплат до даты ухода","Порядок передачи дел и клиентской воронки","Освобождение от части активной работы в переходный период","Нейтральная рекомендация","Корректная внутренняя и внешняя коммуникация причины ухода"]'::jsonb,
  '["Переговорщик не может принуждать сотрудника к заявлению по собственному желанию или соглашению сторон","Переговорщик не может угрожать ухудшением положения при отказе","Переговорщик не может обещать неподтверждённые выплаты или гарантии","Решение о прекращении сотрудничества принято, но конкретные условия должны оставаться предметом добровольных переговоров"]'::jsonb,
  '["Угрозы и понуждение к увольнению","Обвинение сотрудника без признания влияния системы продаж","Обещания сверх полномочий","Преждевременное раскрытие предела компенсации","Эскалация личного конфликта","Сведение переговоров только к размеру денежной выплаты","Формулировки, способные создать трудовые или репутационные риски"]'::jsonb,
  'Компания и Алексей достигают добровольной и конкретной договорённости о прекращении сотрудничества на приемлемых для компании условиях либо, если соглашение не достигнуто на первой встрече, обе стороны точно понимают позиции, обсуждаемый пакет и согласованный следующий шаг без эскалации и юридически рискованного давления.',
  '["Согласовать, продолжается ли сотрудничество","Если нет — зафиксировать пакет обсуждаемых условий и дату прекращения работы","Определить порядок передачи дел и клиентских контактов","Согласовать рекомендацию и формулировки коммуникации","Назначить следующий контакт или оформление с HR без требования немедленной подписи"]'::jsonb,
  'Кейс основан на документе «Сложное увольнение менеджера по продажам». Оценка должна учитывать одновременно результативность, справедливость распределения ответственности и добровольность соглашения. Методология выбирается пользователем из доступных общих методик.',
  null,
  0,
